        if not vals:
            return {"mean": None, "sum": None, "max": None, "min": None, "std": None}
        n = len(vals)
        ssum = sum(vals)
        mean = ssum / n
        mx = max(vals)
        mn = min(vals)
        # population standard deviation
        var = sum((v - mean) ** 2 for v in vals) / n
        std = math.sqrt(var)
        return {"mean": mean, "sum": ssum, "max": mx, "min": mn, "std": std}

